import json,pathlib,hashlib,datetime,copy,sys
R=pathlib.Path(__file__).resolve().parents[2];D=R/'audits/resource-policy-v2-review';sys.path.insert(0,str(R/'scripts'));import validate
load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
b=load(R/'audits/blind-binding-learning-resources-policy-v2.json');now=datetime.datetime.now(datetime.timezone.utc).isoformat();p=load(R/'data/learning-resource-policy.json');assert hashlib.sha256(validate.canonical_json(p).encode()).hexdigest()==b['policy']['sha256']
for c in b['codeFiles']:assert sha(R/c['path'])==c['sha256'],c['path']
tools=[r for rs in load(R/'data/learning-tools-course.json')['learningTools'].values() for r in rs]
for t in tools:assert validate.question_hash(t)==next(z['sha256'] for z in b['resourceBindings'] if z['id']==t['id'])
tr=load(R/'data/learning-tool-reviews.json');pr=load(R/'data/learning-resource-policy-reviews.json');assert not any(r['id']=='contracts-learning-resource-policy-v2' for r in pr);assert not any(r['id'].startswith('contracts-learning-tool-v2-') for r in tr)
evidence=[str(x.relative_to(R)) for x in [D/'binding-and-payload-checks.json',D/'runtime-mutation-checks.json',D/'python-mutation-checks.json',D/'policy-linkage-reproduction.json',D/'independent-math-checks.json']]
new=[]
for t in tools:
 old=next(r for r in tr if r['toolId']==t['id'] and r['toolVersion']==1)
 r=copy.deepcopy(old);r.update(id='contracts-learning-tool-v2-'+t['id'],reviewedAt=now,toolVersion=t['version'],toolSha256=validate.question_hash(t),evidencePaths=old['evidencePaths']+evidence,priorExposure='Nonblind implementation revision review. Prior v1 resource keys, solutions and implementations were seen. Exact computational payload identity was independently checked, and current implementations rerun against the original source-first independent derivations plus 13,000 new seeded cases. No claim of fresh blindness.',scope='Exact v2 mathematical generator/configuration behavior, source assumptions and unchanged payload verified. This does not approve the separate extractor policy: policy 1.0.1 remains flagged for a Python implementation-policy binding mismatch, so course resources must remain inactive. Actual browser QA remains blocked, not passed.',priorReviewId=old['id'])
 new.append(r)
finding={'id':'LR-P05','severity':'blocking-defense-in-depth','area':'Python implementation-policy binding parity','targets':['scripts/learning_resources.py:tool_reasons','scripts/learning_resources.py:integrity_errors'],'finding':'For a correctly hashed actual implementation file with a distinct current tool approval, Python tool_reasons and integrity_errors accept when that file is omitted from or conflicts with approved policy.codeHashes. JavaScript rejects the identical tool. The complete omitted-file reproduction has no policy code errors and valid current policy approval, so this is not merely a malformed policy fixture.','requiredRepair':'Require every implementationFiles path/hash pair to match the active approved policy code inventory in the Python gate, including missing inventories, omissions and mismatches; preserve on-disk hash checks. Add end-to-end Python/JS parity regressions. Advance the policy version and hash after the source change. Tool objects need not change if their bound JS files remain exact.','evidence':'audits/resource-policy-v2-review/policy-linkage-reproduction.json'}
review={'id':'contracts-learning-resource-policy-v2','reviewerId':'robotics-contracts-independent-reviewer','reviewedAt':now,'resourceId':p['id'],'resourceVersion':p['version'],'resourceSha256':b['policy']['sha256'],'decision':'flagged','checks':{'exactProjection':True,'contextPreservation':True,'sourceAndReviewBinding':False,'failClosedMutationTests':False,'runtimeTests':False},'findings':[finding],'priorFindingDispositions':{'LR-P01':'Fixed: removal, bank switch, current record/review/source/policy changes revoke registry, cached render, interactions, restoration and exports. Historical identity does not inherit reapproval.','LR-P02':'Fixed: complete detached source fields and solution context retained; 6398 real-bank contexts had zero altered/omitted original fields and supplemental evidence is inert text in structural UI.','LR-P03':'Fixed for literal keys, cardinality, stable IDs, conditional-intended separation and trimmed independent identities in both languages. Residual policy implementation linkage is separately LR-P05.','LR-P04':'Fixed: positive bounded integral page/count, identity/hash, inspection and explicit disposition probes pass in both languages.'},'codeHashes':p['codeHashes'],'evidencePaths':evidence,'priorExposure':'Prior v1 policy/tool/code seen; this is a disclosed nonblind revision review.','runtimeExplanation':'49 independent Node mutation/structural groups passed; Python 27 of29 probes passed, with the omitted/conflicting policy implementation cases failing. Independent arithmetic rerun passed39 fixed examples,5 complete traces,13000 new-seed cases,13000 distinct rounded alternative checks and13000 replays. Shared targeted53 Node and12 Python tests passed but missed the residual. Actual browser launch remains denied and was not attempted.','browserStatus':'blocked_not_retried','reviewBoundary':'A math/configuration approval does not authorize the separate extraction/activation policy, whole-course completeness, or browser layout.'}
write(R/'data/learning-tool-reviews.json',tr+new);write(R/'data/learning-resource-policy-reviews.json',pr+[review])
summary={'frozenAt':now,'packetSha256':b['packetSha256'],'policyVersion':p['version'],'policySha256':b['policy']['sha256'],'policyDecision':'flagged','toolReviewsAppended':18,'toolVersions':2,'toolReviewFile':'data/learning-tool-reviews.json','toolReviewFileSha256':sha(R/'data/learning-tool-reviews.json'),'policyReviewFile':'data/learning-resource-policy-reviews.json','policyReviewFileSha256':sha(R/'data/learning-resource-policy-reviews.json'),'priorObjectsPreserved':True,'findings':[finding],'evidence':[{'path':e,'sha256':sha(R/e)} for e in evidence],'passed':{'payloadIdentity':18,'frozenFiles':19,'independentNodeGroups':49,'independentPythonGroups':27,'fixedExamples':39,'completeTraces':5,'newSeedCases':13000,'projectionContexts':6398,'contextOmissions':0},'activation':'All course resources remain inactive until an exact-hash repaired policy is independently approved.','next':'Author repairs Python policy linkage; reviewer proceeds to lecture concept-ledger challenge while awaiting the narrow new packet.','restrictions':['Never use /tmp/robotics-l35-venv or the L48 incident environment.','No new dependencies/models/checkpoints/audio/NLTK or denied original L49 notebook retrieval.','No browser retry, installation, alternate restricted route or bypass. Actual browser layout remains unverified after socket denial.','No denied ROS 2 Humble QoS page retry/mirror.','Default installed Python/Node and local source inspection only. No Git/canonical bank writes.']}
write(D/'summary.json',summary)
(D/'HANDOFF.md').write_text('# Resource-policy v2 independent review\n\nPolicy 1.0.1 is flagged for one remaining Python implementation-to-policy binding defect, LR-P05. Full reproducible case, exact bindings and evidence hashes are in summary.json. All four original policy finding groups are otherwise repaired.\n\nEighteen exact v2 tool configurations/computations have separate current reviews, with original v1 reviews preserved. Computational payloads are unchanged and the current implementations passed 39 fixed answers, five full traces, and 13,000 new-seed arithmetic/alternative/replay checks. All 49 independent Node groups passed; Python passed 27 of29, failing the two policy inventory cases. Projection retained 6,398 contexts without omitted or altered original fields. These are disclosed nonblind revision checks.\n\nAll course tools stay inactive until the repaired policy receives exact-hash independent approval. The narrow Python fix can leave the18 tool object hashes unchanged if no bound JS implementation changes. Next review work is the lecture concept-ledger coverage challenge.\n\nActual browser QA remains blocked, not passed, and was not retried. Never use /tmp/robotics-l35-venv or the L48 incident temporary environment. No dependency/model/checkpoint/audio/NLTK downloads, denied original L49 notebook, browser bypass or alternate restricted route. Do not retry the denied ROS2 Humble QoS page by mirror/browser. Default installed Python/Node deterministic checks and local source inspection remain allowed. No Git or canonical bank writes.\n')
print(json.dumps(summary,indent=2))
